internal class GUPPriceEngineTradeAgreementLineAggregation extends GUPPriceEngineAbstractLineAggregation
{

    // List<GUPPriceEngineDecoratedPriceLine> that contains GUPPriceEngineTradeAgreementLine.
    // Stores all compete journal lines -- lines with exactly same AttributeHeaderGroup + AttributeLineGroup
    List lineList;

    // Must be with same currency. 
    real lowestPrice = 0;

    // Length of lineList
    int listLength = 0;

}

Method.Source:
    public void new ()
    {
        this.lineList = new List(Types::AnyType);
        this.lineRecIdSet = new Set(Types::Int64);

        this.lowestPrice = realMax();           
    }

    public void addCompeteLine(GUPPriceEngineTradeAgreementLine _line, int _linePriority, real _linePrice)
    {
        if(this.attributeGroupKey != null && this.attributeGroupKey != _line.parmAttributeGroupKey())
        {
            Error("Lines in aggregation must have same attribute group key.");
        }

        this.attributeGroupKey = _line.parmAttributeGroupKey();

        lineRecIdSet.add(_line.parmJournalLineRecId());
        
        GUPPriceEngineDecoratedPriceLine decoratedLine =
            GUPPriceEngineDecoratedPriceLine::newInstanceByPriceAndLine(_linePrice, _line);
        lineList.addEnd(decoratedLine);

        this.listLength ++;

        this.linePriority = _linePriority;
        if(_linePrice < this.lowestPrice)
        {
            this.lowestPrice = _linePrice;
        }

    }

public void sortJournalLineList()
{
    GUPListSorter listSorter = GUPListSorter::getInstance();
    GUPComparatorDecoratedPriceLine journalComparator = new GUPComparatorDecoratedPriceLine();
    this.lineList = listSorter.sortList(this.lineList, journalComparator);
}

    /// <summary>
    /// Used when attributeGroupKey is same, to avoid hash collision.
    /// </summary>
    /// <param name = "_newLine">Another line to compare.</param>
    /// <returns>True if two lines are compete.</returns>
    public boolean canAddAsCompeteLine(GUPPriceEngineAbstractLine _newLine)
    {
        if (listLength == 0)
        {
            return true;
        }

        ListEnumerator enumerator = this.lineList.getEnumerator();
        enumerator.moveNext();
        return _newLine.isCompeteLine(enumerator.current());
    }
